contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 id) public payable {
        // Setup: schedule an operation using this contract as proposer and executor.
        // The id is derived from the parameters, so it is uniquely determined and unknown a priori.
        address target = address(this);
        uint256 value = 0;
        bytes memory data = hex"";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = id;
        uint256 delay = 0;

        // We need PROPOSER_ROLE to schedule. The test contract is deployed by the caller
        // who also deployed c, but roles may not be set. To ensure we can schedule,
        // we first grant ourselves the PROPOSER_ROLE via the admin (TIMELOCK_ADMIN_ROLE)
        // which is held by the test contract (address(this)) because the constructor
        // gave TIMELOCK_ADMIN_ROLE to _msgSender() (the deployer) and address(this).
        bytes32 proposerRole = c.PROPOSER_ROLE();
        c.grantRole(proposerRole, address(this));

        // Schedule the operation. The hash is computed internally; the resulting id
        // is the one we pass in, so getTimestamp(id) must become positive.
        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 beforeCancel = c.getTimestamp(id);
        require(beforeCancel > 0, "not scheduled");

        // Cancel the scheduled operation. We already have PROPOSER_ROLE.
        c.cancel(id);

        uint256 afterCancel = c.getTimestamp(id);

        // General rule: after a successful cancel, the timestamp of that operation id is zero.
        assert(afterCancel == 0);
    }

    receive() external payable {}
}

