contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 minDelay, address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 extraDelay) public payable {
        require(address(this).balance >= value, "insufficient balance");

        // create an operation id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        
        // schedule it with delay > current minDelay (which is minDelay passed to constructor)
        uint256 delay = c.getMinDelay() + extraDelay + 1;
        c.schedule(target, value, data, predecessor, salt, delay);
        
        // now check the pending status
        bool pending = c.isOperationPending(id);
        bool operation = c.isOperation(id);
        
        // the operation must be pending and considered an operation
        assert(pending && operation);
    }
    
    receive() external payable {}
}

