    }

    function run(bytes32 id) public payable {
        // Bound the parameter: keep id nonzero to distinguish from the zero-role sentinel.
        require(id != bytes32(0), "id must be nonzero");

        // Read-only call: if the operation is not scheduled, it cannot be ready.
        bool operationExists = c.isOperation(id);
        bool ready = c.isOperationReady(id);

        assert(!(!operationExists && ready));
    }

