}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 id) public payable {
        // Bound the parameter: keep id nonzero to avoid the zero-operation sentinel.
        require(id != bytes32(0), "id must be nonzero");

        // Read-only deciding call.
        bool ready = c.isOperationReady(id);

        // Only one comparison: if not ready, the rule is vacuously true; if ready, id must be an operation.
        assert(!ready || c.isOperation(id));
    }

    receive() external payable {}
}
